3	import org.junit.jupiter.api.Tag;
4	import org.junit.jupiter.api.Test;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
6	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
7	import tools.jackson.databind.node.ObjectNode;
8	
9	/** postcode: a 4-digit 'postcode' valid for the owner's city is stored and returned; a
10	 * malformed postcode is rejected (400). Postcode is validated WHEN PRESENT but optional when
11	 * absent, so every earlier requirement's minimal owner (which sends no postcode) stays valid at
12	 * this and all later checkpoints -- the operative request contract stays backward-compatible. */
13	@Tag("cp29")
14	class Cp29Tests extends AcceptanceBase {
15	
16		@Test
17		void coreStoresValidPostcode() throws Exception {
18			int id = createOwnerOk(withPostcode(ownerNode()));
19			getOwner(id).andExpect(jsonPath("$.postcode").value("2000"));
20		}
21	
22		@Test
23		void coreAcceptsOwnerWithoutPostcode() throws Exception {
24			createOwner(ownerNode()).andExpect(status().is2xxSuccessful());
25		}
26	
27		@Test
28		void errorRejectsMalformedPostcode() throws Exception {
29			ObjectNode o = ownerNode();
30			o.put("postcode", "12");
31			createOwner(o).andExpect(status().isBadRequest());
32		}
33	}
